import{_ as i,W as o,s as l,u as d,ah as r,I as e,w as s,Z as t,A as p}from"./chunks/framework.Dx7wo2et.js";import"./chunks/theme.CjgFg8Ql.js";const C=JSON.parse('{"title":"Python 中使用 argparse 解析命令行参数 | LCTT x X-CMD","titleTemplate":false,"description":"Python 中使用 argparse 解析命令行参数 | LCTT (202111) | X-CMD","frontmatter":{"pageClass":"x-blog","head":[["meta",{"name":"og:title","content":"Python 中使用 argparse 解析命令行参数 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Python 中使用 argparse 解析命令行参数 | LCTT (202111) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202111/20210816 Parse command-line arguments with argparse in Python","title":"Python 中使用 argparse 解析命令行参数","tag":"202111"},"relativePath":"202111/20210816 Parse command-line arguments with argparse in Python.md","filePath":"[post].md"}'),c={name:"202111/20210816 Parse command-line arguments with argparse in Python.md"};function u(g,a,h,m,v,b){const n=o("Link");return d(),l("div",null,[a[20]||(a[20]=r(`<h1 id="python-中使用-argparse-解析命令行参数" tabindex="-1">Python 中使用 argparse 解析命令行参数 <a class="header-anchor" href="#python-中使用-argparse-解析命令行参数" aria-label="Permalink to Python 中使用 argparse 解析命令行参数">​</a></h1><blockquote><p>使用 argparse 模块为应用程序设置命令行选项。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202111/15/110139bakkfdt4zoadqiv0.jpg" alt=""></p><p>有一些第三方库用于命令行解析，但标准库 <code>argparse</code> 与之相比也毫不逊色。</p><p>无需添加很多依赖，你就可以编写带有实用参数解析功能的漂亮命令行工具。</p><h3 id="python-中的参数解析" tabindex="-1">Python 中的参数解析 <a class="header-anchor" href="#python-中的参数解析" aria-label="Permalink to Python 中的参数解析">​</a></h3><p>使用 <code>argparse</code> 解析命令行参数时，第一步是配置一个 <code>ArgumentParser</code> 对象。这通常在全局模块内完成，因为单单_配置_一个解析器没有副作用。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>import argparse</span></span>
<span class="line"><span></span></span>
<span class="line"><span>PARSER = argparse.ArgumentParser()</span></span></code></pre></div><p><code>ArgumentParser</code> 中最重要的方法是 <code>.add_argument()</code>，它有几个变体。默认情况下，它会添加一个参数，并期望一个值。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>PARSER.add_argument(&quot;--value&quot;)</span></span></code></pre></div><p>查看实际效果，调用 <code>.parse_args()</code>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>PARSER.parse_args([&quot;--value&quot;, &quot;some-value&quot;])</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Namespace(value=&#39;some-value&#39;)</span></span></code></pre></div><p>也可以使用 <code>=</code> 语法：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>PARSER.parse_args([&quot;--value=some-value&quot;])</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Namespace(value=&#39;some-value&#39;)</span></span></code></pre></div><p>为了缩短在命令行输入的命令，你还可以为选项指定一个短“别名”：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>PARSER.add_argument(&quot;--thing&quot;, &quot;-t&quot;)</span></span></code></pre></div><p>可以传入短选项：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>PARSER.parse_args(&quot;-t some-thing&quot;.split())</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Namespace(value=None, thing=&#39;some-thing&#39;)</span></span></code></pre></div><p>或者长选项：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>PARSER.parse_args(&quot;--thing some-thing&quot;.split())</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Namespace(value=None, thing=&#39;some-thing&#39;)</span></span></code></pre></div><h3 id="类型" tabindex="-1">类型 <a class="header-anchor" href="#类型" aria-label="Permalink to 类型">​</a></h3><p>有很多类型的参数可供你使用。除了默认类型，最流行的两个是布尔类型和计数器。布尔类型有一个默认为 <code>True</code> 的变体和一个默认为 <code>False</code> 的变体。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>PARSER.add_argument(&quot;--active&quot;, action=&quot;store_true&quot;)</span></span>
<span class="line"><span>PARSER.add_argument(&quot;--no-dry-run&quot;, action=&quot;store_false&quot;, dest=&quot;dry_run&quot;)</span></span>
<span class="line"><span>PARSER.add_argument(&quot;--verbose&quot;, &quot;-v&quot;, action=&quot;count&quot;)</span></span></code></pre></div><p>除非显式传入 <code>--active</code>，否则 <code>active</code> 就是 <code>False</code>。<code>dry-run</code> 默认是 <code>True</code>，除非传入 <code>--no-dry-run</code>。无值的短选项可以并列。</p><p>传递所有参数会导致非默认状态：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>PARSER.parse_args(&quot;--active --no-dry-run -vvvv&quot;.split())</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Namespace(value=None, thing=None, active=True, dry_run=False, verbose=4)</span></span></code></pre></div><p>默认值则比较单一：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>PARSER.parse_args(&quot;&quot;.split())</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Namespace(value=None, thing=None, active=False, dry_run=True, verbose=None)</span></span></code></pre></div><h3 id="子命令" tabindex="-1">子命令 <a class="header-anchor" href="#子命令" aria-label="Permalink to 子命令">​</a></h3><p>经典的 Unix 命令秉承了“一次只做一件事，并做到极致”，但现代的趋势把“几个密切相关的操作”放在一起。</p><p><code>git</code>、<code>podman</code> 和 <code>kubectl</code> 充分说明了这种范式的流行。<code>argparse</code> 库也可以做到：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>MULTI_PARSER = argparse.ArgumentParser()</span></span>
<span class="line"><span>subparsers = MULTI_PARSER.add_subparsers()</span></span>
<span class="line"><span>get = subparsers.add_parser(&quot;get&quot;)</span></span>
<span class="line"><span>get.add_argument(&quot;--name&quot;)</span></span>
<span class="line"><span>get.set_defaults(command=&quot;get&quot;)</span></span>
<span class="line"><span>search = subparsers.add_parser(&quot;search&quot;)</span></span>
<span class="line"><span>search.add_argument(&quot;--query&quot;)</span></span>
<span class="line"><span>search.set_defaults(command=&quot;search&quot;)</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>MULTI_PARSER.parse_args(&quot;get --name awesome-name&quot;.split())</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Namespace(name=&#39;awesome-name&#39;, command=&#39;get&#39;)</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>MULTI_PARSER.parse_args(&quot;search --query name~awesome&quot;.split())</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Namespace(query=&#39;name~awesome&#39;, command=&#39;search&#39;)\`</span></span></code></pre></div><h3 id="程序架构" tabindex="-1">程序架构 <a class="header-anchor" href="#程序架构" aria-label="Permalink to 程序架构">​</a></h3><p>使用 <code>argparse</code> 的一种方法是使用下面的结构：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>## my_package/__main__.py</span></span>
<span class="line"><span>import argparse</span></span>
<span class="line"><span>import sys</span></span>
<span class="line"><span></span></span>
<span class="line"><span>from my_package import toplevel</span></span>
<span class="line"><span></span></span>
<span class="line"><span>parsed_arguments = toplevel.PARSER.parse_args(sys.argv[1:])</span></span>
<span class="line"><span>toplevel.main(parsed_arguments)</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>## my_package/toplevel.py</span></span>
<span class="line"><span></span></span>
<span class="line"><span>PARSER = argparse.ArgumentParser()</span></span>
<span class="line"><span>## .add_argument, etc.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>def main(parsed_args):</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    ...</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    # do stuff with parsed_args</span></span></code></pre></div>`,46)),e("p",null,[a[1]||(a[1]=s("在这种情况下，使用 ")),a[2]||(a[2]=e("code",null,"python -m my_package",-1)),a[3]||(a[3]=s(" 运行。或者，你可以在包安装时使用 ")),t(n,{href:"https://python-packaging.readthedocs.io/en/latest/command-line-scripts.html#the-console-scripts-entry-point"},{default:p(()=>a[0]||(a[0]=[s("console_scprits")])),_:1}),a[4]||(a[4]=s(" 入口点。"))]),a[21]||(a[21]=e("h3",{id:"总结",tabindex:"-1"},[s("总结 "),e("a",{class:"header-anchor",href:"#总结","aria-label":"Permalink to 总结"},"​")],-1)),a[22]||(a[22]=e("p",null,[e("code",null,"argparse"),s(" 模块是一个强大的命令行参数解析器，还有很多功能没能在这里介绍。它能实现你想象的一切。")],-1)),a[23]||(a[23]=e("hr",null,null,-1)),e("p",null,[a[6]||(a[6]=s("via: ")),t(n,{href:"https://opensource.com/article/21/8/python-argparse"},{default:p(()=>a[5]||(a[5]=[s("https://opensource.com/article/21/8/python-argparse")])),_:1})]),e("p",null,[a[11]||(a[11]=s("作者：")),t(n,{href:"https://opensource.com/users/moshez"},{default:p(()=>a[7]||(a[7]=[s("Moshe Zadka")])),_:1}),a[12]||(a[12]=s(" 选题：")),t(n,{href:"https://github.com/lujun9972"},{default:p(()=>a[8]||(a[8]=[s("lujun9972")])),_:1}),a[13]||(a[13]=s(" 译者：")),t(n,{href:"https://github.com/MjSeven"},{default:p(()=>a[9]||(a[9]=[s("MjSeven")])),_:1}),a[14]||(a[14]=s(" 校对：")),t(n,{href:"https://github.com/wxy"},{default:p(()=>a[10]||(a[10]=[s("wxy")])),_:1})]),e("p",null,[a[17]||(a[17]=s("本文由 ")),t(n,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>a[15]||(a[15]=[s("LCTT")])),_:1}),a[18]||(a[18]=s(" 原创编译，")),t(n,{href:"https://linux.cn/"},{default:p(()=>a[16]||(a[16]=[s("Linux中国")])),_:1}),a[19]||(a[19]=s(" 荣誉推出"))])])}const q=i(c,[["render",u]]);export{C as __pageData,q as default};
